+uint64_t validate_ir2_filter(const PlanFilterV2 &filter, uint32_t variables, uint64_t bound) {
+    if (filter.nodes.empty() || filter.nodes.size() > detail::MAX_RULE_EXPRESSION_NODES)
+        ir2_error("filter node count");
+    std::array<size_t, detail::MAX_EXPRESSION_HEIGHT> heights{};
+    size_t depth = 0;
+    uint64_t used = 0;
+    for (size_t i = 0; i < filter.nodes.size(); ++i) {
+        const auto &node = filter.nodes[i];
+        (void)ir2_opcode(node.op);
+        if (node.op == PlanOpcodeV2::Literal || node.op == PlanOpcodeV2::Variable) {
+            if (depth == heights.size()) ir2_error("filter operand stack exceeds 32");
+            if (node.op == PlanOpcodeV2::Literal) {
+                const auto *value = std::get_if<Value>(&node.operand);
+                if (!value) ir2_error("literal node does not own a Value");
+                detail::TypedDomain::validate_value(*value);
+            } else {
+                const auto *variable = std::get_if<uint32_t>(&node.operand);
+                if (!variable || *variable >= variables || !(bound & (uint64_t(1) << *variable)))
+                    ir2_error("filter variable is not positively bound");
+                used |= uint64_t(1) << *variable;
