+            heights[depth++] = 1;
+        } else {
+            if (!std::holds_alternative<std::monostate>(node.operand)) ir2_error("operator has an operand payload");
+            if (node.op == PlanOpcodeV2::Negate) {
+                if (!depth) ir2_error("unary filter stack underflow");
+                if (++heights[depth - 1] > detail::MAX_EXPRESSION_HEIGHT) ir2_error("filter AST exceeds 32");
+            } else {
+                if (depth < 2) ir2_error("binary filter stack underflow");
+                const auto height = 1 + std::max(heights[depth - 1], heights[depth - 2]);
+                if (height > detail::MAX_EXPRESSION_HEIGHT) ir2_error("filter AST exceeds 32");
+                if (ir2_comparison(node.op) && (i + 1 != filter.nodes.size() || depth != 2))
