+class IR2Writer {
+    std::string out;
+public:
+    void append(const std::string &s) {
+        if (s.size() > PROGRAM_IR_V2_MAX_BYTES - out.size())
+            throw Error("TD_E_IR_LIMIT: IR2 exceeds 4194304 encoded bytes");
+        out.append(s);
+    }
+    void character(char c) {
+        if (out.size() == PROGRAM_IR_V2_MAX_BYTES)
+            throw Error("TD_E_IR_LIMIT: IR2 exceeds 4194304 encoded bytes");
+        out.push_back(c);
+    }
+    void number(uint64_t n) { append(std::to_string(n)); }
+    void boolean(bool b) { append(b ? "true" : "false"); }
+    void string(const std::string &s) {
+        constexpr char hex[] = "0123456789abcdef";
+        character('"');
+        for (unsigned char c : s) {
+            if (c == '"' || c == '\\') { character('\\'); character(static_cast<char>(c)); }
+            else if (c < 0x20) { append("\\u00"); character(hex[c >> 4]); character(hex[c & 15]); }
+            else character(static_cast<char>(c));
+        }
+        character('"');
+    }
+    void value(const Value &v) {
+        switch (v.tag()) {
+        case ValueTag::String: append("{\"t\":\"str\",\"v\":"); string(v.as_str()); break;
+        case ValueTag::Boolean: append("{\"t\":\"bool\",\"v\":"); boolean(v.as_bool()); break;
+        case ValueTag::Int64: append("{\"t\":\"i64\",\"v\":"); string(std::to_string(v.as_i64())); break;
+        case ValueTag::Float64: {
+            constexpr char hex[] = "0123456789abcdef";
+            const auto bits = detail::canonical_float_bits(detail::float_bits(v.as_f64()));
+            if (!detail::finite_float_bits(bits)) ir2_error("nonfinite literal");
+            append("{\"t\":\"f64\",\"v\":\"");
+            for (int shift = 60; shift >= 0; shift -= 4) character(hex[(bits >> shift) & 15]);
+            character('"'); break;
+        }
+        default: ir2_error("literal tag");
+        }
+        character('}');
+    }
+    void terms(const std::vector<PlanTerm> &terms) {
+        character('['); bool first = true;
+        for (const auto &term : terms) {
+            if (!first) character(','); first = false;
+            if (const auto *variable = std::get_if<uint32_t>(&term.value)) {
+                append("{\"var\":"); number(*variable); character('}');
+            } else { append("{\"const\":"); value(std::get<Value>(term.value)); character('}'); }
+        }
+        character(']');
+    }
+    void atom(const PlanAtom &a) { append("{\"relation\":"); number(a.relation); append(",\"terms\":"); terms(a.terms); character('}'); }
+    void ids(const std::vector<uint32_t> &ids) {
+        character('['); bool first = true;
+        for (auto id : ids) { if (!first) character(','); first = false; number(id); }
+        character(']');
+    }
+    std::string finish() { return std::move(out); }
+};
