+    }
+    auto own_atom = [&](const Atom &a) {
+        PlanAtom owned{static_cast<uint32_t>(a.relation),{}};
+        for (const auto &t : a.terms) {
+            if (t.variable) owned.terms.push_back({t.id});
+            else owned.terms.push_back({parsed.dictionary.decode(t.id)});
+        }
+        return owned;
+    };
+    for (uint32_t r = 0; r < parsed.rules.size(); ++r) {
+        const auto &rule = parsed.rules[r];
+        PlanRuleV2 owned{r,static_cast<uint32_t>(rule.variables),own_atom(rule.head),{}, {}};
+        for (const auto &p : parsed.signed_rules[r].body) owned.body.push_back({p.negative,own_atom(parsed.signed_atom(r,p))});
+        for (const auto &filter : rule.filters) {
